import os,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
from collections import deque
def comps(g,target):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==target and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            p=(a+dy,b+dx)
                            if 0<=p[0]<H and 0<=p[1]<W and not seen[p[0]][p[1]] and g[p[0]][p[1]]==target:
                                seen[p[0]][p[1]]=True; q.append(p)
                out.append(cells)
    return out
def rel(cells):
    mr=min(r for r,c in cells); mc=min(c for r,c in cells)
    return [(r-mr,c-mc) for r,c in cells]
